// ---- Run-once builders compile without optimization ----
// Saves ~4 s of build time; their cost is the XAML calls anyway. Never use it
// on anything per frame, per tick or per media update.
#define COLD_UNOPTIMIZED [[clang::optnone]]

// ---- Ignored exceptions leave a trace ----
// XAML/WinRT failures are swallowed so Explorer survives, but each catch site
// logs where it happened (at most 3 times, so per-frame failures can't flood).
// The last errors the mod caught, for bug reports.
static std::mutex g_recentErrorsMutex;
static std::vector<std::wstring> g_recentErrors;

static void RememberError(const std::wstring& what) {
    SYSTEMTIME st; GetLocalTime(&st);
    wchar_t stamp[32];
    swprintf_s(stamp, L"%02d:%02d:%02d  ", st.wHour, st.wMinute, st.wSecond);
    std::lock_guard<std::mutex> lk(g_recentErrorsMutex);
    if (g_recentErrors.size() >= 30) g_recentErrors.erase(g_recentErrors.begin());
    g_recentErrors.push_back(stamp + what);
}

static void LogIgnoredExceptionAt(const char* func, int line) {
    const std::wstring where = std::wstring(func, func + strlen(func)) + L":" + std::to_wstring(line);
    try {
        throw;
    } catch (winrt::hresult_error const& e) {
        Wh_Log(L"Ignored exception in %S (line %d): HRESULT 0x%08X %s",
               func, line, (unsigned)e.code().value, e.message().c_str());
        wchar_t hr[16];
        swprintf_s(hr, L"0x%08X", (unsigned)e.code().value);
        RememberError(where + L"  " + hr + L"  " + e.message().c_str());
    } catch (std::exception const& e) {
        Wh_Log(L"Ignored exception in %S (line %d): %S", func, line, e.what());
        const std::string what = e.what();
        RememberError(where + L"  " + std::wstring(what.begin(), what.end()));
    } catch (...) {
        Wh_Log(L"Ignored exception in %S (line %d)", func, line);
        RememberError(where);
    }
}
#define LOG_IGNORED_EXCEPTION()                                                   \
    do {                                                                          \
        static std::atomic<int> s_ignoredCount{0};                                \
        if (s_ignoredCount.fetch_add(1, std::memory_order_relaxed) < 3)           \
            LogIgnoredExceptionAt(__func__, __LINE__);                            \
    } while (0)

