static UiLanguage WindowsUiLanguage() {
    const LANGID id = GetUserDefaultUILanguage();
    switch (PRIMARYLANGID(id)) {
        case LANG_UKRAINIAN:  return UiLanguage::Ukrainian;
        case LANG_RUSSIAN:    return UiLanguage::Russian;
        case LANG_GERMAN:     return UiLanguage::German;
        case LANG_HINDI:      return UiLanguage::Hindi;
        case LANG_CHINESE:
            switch (SUBLANGID(id)) {
                case SUBLANG_CHINESE_TRADITIONAL:
                case SUBLANG_CHINESE_HONGKONG:
                case SUBLANG_CHINESE_MACAU:
                    return UiLanguage::ChineseTraditional;
                default:
                    return UiLanguage::ChineseSimplified;
            }
        case LANG_SPANISH:    return UiLanguage::Spanish;
        case LANG_FRENCH:     return UiLanguage::French;
        case LANG_PORTUGUESE: return UiLanguage::PortugueseBrazil;
        case LANG_ITALIAN:    return UiLanguage::Italian;
        case LANG_POLISH:     return UiLanguage::Polish;
        case LANG_TURKISH:    return UiLanguage::Turkish;
        case LANG_JAPANESE:   return UiLanguage::Japanese;
        case LANG_KOREAN:     return UiLanguage::Korean;
        default:              return UiLanguage::English;
    }
}

static UiLanguage ResolveSettingsUiLanguage() {
    const std::wstring lang = GetSettingOverride(L"SettingsWindowSettings.settingsLanguage",
                                                 g_settings.settingsLanguage);
    if (lang.empty() || lang == L"auto") return WindowsUiLanguage();
    if (lang == L"uk") return UiLanguage::Ukrainian;
    if (lang == L"ru") return UiLanguage::Russian;
    if (lang == L"de") return UiLanguage::German;
    if (lang == L"hi") return UiLanguage::Hindi;
    if (lang == L"zh-Hans" || lang == L"zh") return UiLanguage::ChineseSimplified;
    if (lang == L"zh-Hant") return UiLanguage::ChineseTraditional;
    if (lang == L"es") return UiLanguage::Spanish;
    if (lang == L"fr") return UiLanguage::French;
    if (lang == L"pt-BR") return UiLanguage::PortugueseBrazil;
    if (lang == L"it") return UiLanguage::Italian;
    if (lang == L"pl") return UiLanguage::Polish;
    if (lang == L"tr") return UiLanguage::Turkish;
    if (lang == L"ja") return UiLanguage::Japanese;
    if (lang == L"ko") return UiLanguage::Korean;
    return UiLanguage::English;
}

static std::wstring Loc(const std::wstring& en) {
    const UiLanguage lang = ResolveSettingsUiLanguage();
    if (lang == UiLanguage::English) return en;

    static const std::unordered_map<std::wstring_view, const LocRow*> index = [] {
        std::unordered_map<std::wstring_view, const LocRow*> m;
        m.reserve(ARRAYSIZE(LOC_TABLE));
        for (const LocRow& row : LOC_TABLE) m.emplace(row.en, &row);
        return m;
    }();
    auto it = index.find(std::wstring_view(en));
    return it != index.end() ? std::wstring(it->second->tr[(int)lang]) : en;
}

