static HINSTANCE ThisModule() {
    HMODULE hm = nullptr;
    GetModuleHandleExW(GET_MODULE_HANDLE_EX_FLAG_FROM_ADDRESS | GET_MODULE_HANDLE_EX_FLAG_UNCHANGED_REFCOUNT,
                       reinterpret_cast<LPCWSTR>(&ThisModule), &hm);
    return hm;
}

static void UnregisterWindowClass() {
    if (!s_classRegistered) return;
    if (UnregisterClassW(s_windowClass, s_classModule)) s_classRegistered = false;
    else Wh_Log(L"Settings window: UnregisterClassW failed (%lu)", GetLastError());
}
