[[maybe_unused]] static const wchar_t* ACCENT_KEY = L"SettingsWindowSettings.accentColor";

static winrt::Windows::UI::Color ContrastColor(winrt::Windows::UI::Color c) {
    double lum = 0.299 * c.R + 0.587 * c.G + 0.114 * c.B;
    return lum > 150.0 ? winrt::Windows::UI::Color{ 255, 0, 0, 0 }
                       : winrt::Windows::UI::Color{ 255, 255, 255, 255 };
}

static wuxm::SolidColorBrush s_accentBrush{ nullptr };

// True while DWM draws Mica / Mica Alt behind the window (see ApplyMica): the XAML surfaces
// then turn transparent so the material shows through, like the cards of Windows 11 Settings.
static bool s_micaOn = false;
static int  s_materialApplied = -1;  // XS_MATERIAL_*, the DWM backdrop type values apart from Acrylic Thin
static wuxc::Grid s_micaHost{ nullptr };  // first child of the root: carries the Mica composition visual
static void UpdateMicaVisual();  // defined with ApplyMica, below BuildUi
#ifndef WH_EDITING
static winrt::Windows::UI::Composition::SpriteVisual s_micaSprite{ nullptr };  // the live Mica layer, if any
static winrt::Windows::UI::Composition::CompositionBrush s_micaFadeBrush{ nullptr };  // for the scroll fades: a blur can't run on a 1px strip
#endif
static bool s_micaActive = true;  // window is active: Mica shows; inactive windows show the solid fallback

// The window itself, and the panel that opens inside a card.
static wuxm::SolidColorBrush WindowBackground() {
    // Under the Mica visual: MicaController's fallback color, seen if the effect cannot be made
    // (transparency effects off, no wallpaper brush).
    if (s_micaOn && s_materialApplied == 4 && s_light) return Brush(255, 0xE8, 0xE8, 0xE8);
    return s_light ? Brush(255, 243, 243, 243) : Brush(255, 32, 32, 32);
}
static wuxm::SolidColorBrush InsetBackground() {
    if (s_micaOn) return s_light ? Brush(0x66, 243, 243, 243) : Brush(0x33, 0, 0, 0);
    return s_light ? Brush(255, 243, 243, 243) : Brush(255, 34, 34, 34);
}
static wuxm::SolidColorBrush s_accentFgBrush{ nullptr };
static wuxm::SolidColorBrush s_accentHoverBrush{ nullptr };
static wuxm::SolidColorBrush s_accentPressedBrush{ nullptr };

// delta > 0 lightens toward white; delta < 0 darkens toward black.
static winrt::Windows::UI::Color ShadeColor(winrt::Windows::UI::Color c, double delta) {
    auto ch = [delta](int v) -> BYTE {
        double t = delta >= 0 ? v + (255 - v) * delta : v * (1.0 + delta);
        return (BYTE)std::clamp(t, 0.0, 255.0);
    };
    return winrt::Windows::UI::Color{ 255, ch(c.R), ch(c.G), ch(c.B) };
}

static void SetOrMakeBrush(wuxm::SolidColorBrush& brush, winrt::Windows::UI::Color c) {
    if (brush) brush.Color(c); else brush = wuxm::SolidColorBrush(c);
}

static winrt::Windows::UI::Color s_accentShown{};  // what the brushes are at, or heading to
static winrt::Windows::UI::Xaml::Media::Animation::Storyboard s_accentFade{ nullptr };

static winrt::Windows::UI::Color AccentTargetColor() {
    auto c = AccentColorValue();
    // Any cover can be picked here, so a very dark one is lifted enough to see.
    if (GetSettingOverride(ACCENT_KEY, g_settings.settingsAccentColor) == L"-2 -2 -2") c = VizEnsureContrast(c);
    return c;
}

static void RefreshAccentBrushes() {
    const auto c = AccentTargetColor();
    if (s_accentFade) {
        try { s_accentFade.Stop(); } catch (...) { LOG_IGNORED_EXCEPTION(); }
        s_accentFade = nullptr;
    }
    s_accentShown = c;
    SetOrMakeBrush(s_accentBrush, c);
    SetOrMakeBrush(s_accentFgBrush, ContrastColor(c));
    SetOrMakeBrush(s_accentHoverBrush, ShadeColor(c, -0.12));   // darker on hover
    SetOrMakeBrush(s_accentPressedBrush, ShadeColor(c, -0.24));  // and more on press
}

static wuxm::SolidColorBrush AccentBrush() {
    if (!s_accentBrush) RefreshAccentBrushes();
    return s_accentBrush;
}
static wuxm::SolidColorBrush AccentForegroundBrush() {
    if (!s_accentFgBrush) RefreshAccentBrushes();
    return s_accentFgBrush;
}

static void ScheduleApply() {
    if (s_applyTimer) { s_applyTimer.Stop(); s_applyTimer.Start(); }
    else ApplySettingsLiveNow();
}

// ---- Motion ----
// Every animation in this window goes through here, so Settings Window >
// Animations (or Windows' own "Animation effects") turns all of them off: then
// values go straight to where they would have ended.
namespace wma = winrt::Windows::UI::Xaml::Media::Animation;

// What the open window was built with: a change to either rebuilds all of it (RebuildWholeUi).
static bool s_uiMotion = true;
static std::wstring s_uiLanguage;
static std::wstring UiLanguageSetting() {
    return GetSettingOverride(L"SettingsWindowSettings.settingsLanguage", g_settings.settingsLanguage);
}
static bool s_uiReportButton = true;
static bool s_uiIconsAboveSave = true;
static bool IconsAboveSaveWanted() {
    return GetSettingOverride(L"SettingsWindowSettings.sidebarIconsAboveSave",
                              g_settings.sidebarIconsAboveSave ? L"1" : L"0") != L"0";
}
static bool ReportButtonWanted() {
    return BugReportsEnabled() &&
           GetSettingOverride(L"SettingsWindowSettings.reportButtonInSidebar",
                              g_settings.reportButtonInSidebar ? L"1" : L"0") != L"0";
}

static bool MotionOn() {
    BOOL system = TRUE;
    SystemParametersInfoW(SPI_GETCLIENTAREAANIMATION, 0, &system, 0);
    return system && GetSettingOverride(L"SettingsWindowSettings.animations",
                                        g_settings.settingsAnimations ? L"1" : L"0") != L"0";
}

static wux::Duration MotionDuration(int ms) {
    return wux::DurationHelper::FromTimeSpan(
        winrt::Windows::Foundation::TimeSpan{ std::chrono::milliseconds(MotionOn() ? ms : 0) });
}

// The window's ease-out, about cubic-bezier(0.23, 1, 0.32, 1).
static wma::EasingFunctionBase StrongEaseOut() {
    wma::ExponentialEase ease;
    ease.Exponent(5.0);
    ease.EasingMode(wma::EasingMode::EaseOut);
    return ease;
}

// One property's move; from where it is unless `from` is given.
struct Tween {
    wux::DependencyObject target;
    const wchar_t* prop;
    double to;
    double from = std::numeric_limits<double>::quiet_NaN();
};

// Runs the moves together. `hold`: keep the end value, so a second call takes
// over smoothly from wherever this one is; otherwise the local value shows
// again when it's done. Returns the storyboard (null if it couldn't start)
// for Completed or Stop.
static wma::Storyboard Animate(std::initializer_list<Tween> tweens, int ms, bool hold = true) {
    try {
        wma::Storyboard sb;
        for (const auto& t : tweens) {
            wma::DoubleAnimation a;
            if (!std::isnan(t.from)) a.From(t.from);
            a.To(t.to);
            a.Duration(MotionDuration(ms));
            a.EasingFunction(StrongEaseOut());
            if (!hold) a.FillBehavior(wma::FillBehavior::Stop);
            wma::Storyboard::SetTarget(a, t.target);
            wma::Storyboard::SetTargetProperty(a, winrt::hstring{ t.prop });
            sb.Children().Append(a);
        }
        sb.Begin();
        return sb;
    } catch (...) { LOG_IGNORED_EXCEPTION(); return nullptr; }
}

static void AnimateTo(wux::DependencyObject const& target, const wchar_t* prop, double to, int ms,
                      double from = std::numeric_limits<double>::quiet_NaN()) {
    Animate({ { target, prop, to, from } }, ms);
}

// Crossfades brushes to new colors, and everything painted with them follows.
// The new color is their value straight away, so it's what's left when this ends.
struct ColorTween {
    wuxm::SolidColorBrush brush;
    winrt::Windows::UI::Color to;
};
static wma::Storyboard AnimateColors(std::initializer_list<ColorTween> tweens, int ms) {
    try {
        wma::CubicEase ease;
        ease.EasingMode(wma::EasingMode::EaseInOut);
        wma::Storyboard sb;
        for (const auto& t : tweens) {
            wma::ColorAnimation a;
            a.From(t.brush.Color());
            a.To(t.to);
            a.Duration(MotionDuration(ms));
            a.EasingFunction(ease);
            a.EnableDependentAnimation(true);
            a.FillBehavior(wma::FillBehavior::Stop);
            t.brush.Color(t.to);
            wma::Storyboard::SetTarget(a, t.brush);
            wma::Storyboard::SetTargetProperty(a, L"Color");
            sb.Children().Append(a);
        }
        sb.Begin();
        return sb;
    } catch (...) { LOG_IGNORED_EXCEPTION(); return nullptr; }
}

// The accent changed from outside this window (a new cover under an album accent).
// Shorter than the timer that calls this, so one fade is over before the next.
static void FollowAccentColor() {
    if (!s_accentBrush) return;
    const auto c = AccentTargetColor();
    if (c == s_accentShown) return;
    if (!MotionOn()) { RefreshAccentBrushes(); return; }
    s_accentShown = c;
    s_accentFade = AnimateColors({
        { s_accentBrush, c },
        { s_accentFgBrush, ContrastColor(c) },
        { s_accentHoverBrush, ShadeColor(c, -0.12) },
        { s_accentPressedBrush, ShadeColor(c, -0.24) },
    }, 450);
}

// Moves in legs: each track goes through its values (values[0] is the start),
// reaching the next one at the end of each leg, eased as that leg says.
struct Track {
    wux::DependencyObject target;
    const wchar_t* prop;
    std::vector<double> values;
};
struct Leg {
    int ms;
    wma::EasingFunctionBase ease;
};
static wma::Storyboard AnimateThrough(std::initializer_list<Track> tracks, std::initializer_list<Leg> legs) {
    try {
        const bool on = MotionOn();
        wma::Storyboard sb;
        for (const auto& tr : tracks) {
            if (tr.values.empty()) continue;
            wma::DoubleAnimationUsingKeyFrames a;
            auto key = [&a](int ms, double v, wma::EasingFunctionBase const& ease) {
                wma::EasingDoubleKeyFrame k;
                k.KeyTime(wma::KeyTimeHelper::FromTimeSpan(
                    winrt::Windows::Foundation::TimeSpan{ std::chrono::milliseconds(ms) }));
                k.Value(v);
                if (ease) k.EasingFunction(ease);
                a.KeyFrames().Append(k);
            };
            key(0, on ? tr.values.front() : tr.values.back(), nullptr);
            if (on) {
                int at = 0;
                size_t i = 1;
                for (const auto& leg : legs) {
                    if (i >= tr.values.size()) break;
                    at += leg.ms;
                    key(at, tr.values[i++], leg.ease);
                }
            }
            wma::Storyboard::SetTarget(a, tr.target);
            wma::Storyboard::SetTargetProperty(a, winrt::hstring{ tr.prop });
            sb.Children().Append(a);
        }
        sb.Begin();
        return sb;
    } catch (...) { LOG_IGNORED_EXCEPTION(); return nullptr; }
}

// The staggered slide-in for a page's cards or a dropdown's items.
static wma::TransitionCollection EntranceTransitions(double fromY) {
    if (!MotionOn()) return nullptr;
    wma::TransitionCollection transitions;
    wma::EntranceThemeTransition entrance;
    entrance.IsStaggeringEnabled(true);
    entrance.FromVerticalOffset(fromY);
    transitions.Append(entrance);
    return transitions;
}

// The hover fade, for control templates' Border.
static std::wstring BrushFadeXaml() {
    return MotionOn() ? L"<Border.BackgroundTransition><BrushTransition Duration=\"0:0:0.083\"/></Border.BackgroundTransition>" : L"";
}

